CREATE OR REPLACE FUNCTION public.create_checkin(_room_id uuid, _guest_id uuid, _package_id uuid) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE chosen_price numeric; number text; BEGIN IF NOT (public.has_role(auth.uid(), 'owner') OR public.is_receptionist(auth.uid())) THEN RAISE EXCEPTION 'Akses ditolak'; END IF; SELECT price INTO chosen_price FROM public.packages WHERE id = _package_id AND active; IF chosen_price IS NULL THEN RAISE EXCEPTION 'Paket tidak tersedia'; END IF; UPDATE public.rooms SET status = 'occupied' WHERE id = _room_id AND status = 'ready' AND active; IF NOT FOUND THEN RAISE EXCEPTION 'Kamar tidak tersedia'; END IF; INSERT INTO public.transactions(guest_id, room_id, status, created_by, price_snapshot) VALUES (_guest_id, _room_id, 'check_in', auth.uid(), chosen_price) RETURNING transaction_number INTO number; RETURN number; END $$;
REVOKE ALL ON FUNCTION public.create_checkin(uuid, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.create_checkin(uuid, uuid, uuid) TO authenticated;